import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import SecretPromptDialog from './SecretPromptDialog';

const callCoreRpc = vi.fn();
vi.mock('../../services/coreRpcClient', () => ({
  callCoreRpc: (...args: unknown[]) => callCoreRpc(...args),
}));

function dispatchRequest(detail: { refId: string; keyName: string; prompt: string }) {
  window.dispatchEvent(new CustomEvent('openhuman:mcp-setup-secret-requested', { detail }));
}

describe('SecretPromptDialog', () => {
  beforeEach(() => {
    callCoreRpc.mockReset();
    callCoreRpc.mockResolvedValue(undefined);
  });

  afterEach(() => {
    // The component cleans up its own listener on unmount via useEffect;
    // we don't need to remove the event listener manually here.
  });

  it('is hidden until an event is dispatched', () => {
    render(<SecretPromptDialog />);
    expect(screen.queryByRole('dialog')).toBeNull();
  });

  it('renders the prompt + key name when an event arrives', async () => {
    render(<SecretPromptDialog />);
    dispatchRequest({
      refId: 'secret://abc123',
      keyName: 'NOTION_API_KEY',
      prompt: 'Paste your Notion integration token.',
    });
    await screen.findByRole('dialog');
    expect(screen.getByText('NOTION_API_KEY')).toBeTruthy();
    expect(screen.getByText('Paste your Notion integration token.')).toBeTruthy();
  });

  it('submits the value via mcp_setup_submit_secret and dismisses', async () => {
    render(<SecretPromptDialog />);
    dispatchRequest({ refId: 'secret://abc123', keyName: 'TOKEN', prompt: '' });
    await screen.findByRole('dialog');

    const input = screen.getByLabelText(/^Value$/i);
    fireEvent.change(input, { target: { value: 'super-secret-value' } });

    const submit = screen.getByText(/^Submit$/);
    fireEvent.click(submit);

    await waitFor(() => {
      expect(callCoreRpc).toHaveBeenCalledWith({
        method: 'openhuman.mcp_setup_submit_secret',
        params: { ref_id: 'secret://abc123', value: 'super-secret-value' },
      });
    });
    await waitFor(() => expect(screen.queryByRole('dialog')).toBeNull());
  });

  it('renders input as type=password by default and toggles on Show/Hide', async () => {
    render(<SecretPromptDialog />);
    dispatchRequest({ refId: 'secret://abc', keyName: 'K', prompt: '' });
    await screen.findByRole('dialog');

    const input = screen.getByLabelText(/^Value$/i) as HTMLInputElement;
    expect(input.type).toBe('password');

    fireEvent.click(screen.getByText(/^Show$/));
    expect((screen.getByLabelText(/^Value$/i) as HTMLInputElement).type).toBe('text');

    fireEvent.click(screen.getByText(/^Hide$/));
    expect((screen.getByLabelText(/^Value$/i) as HTMLInputElement).type).toBe('password');
  });

  it('cancel does not call mcp_setup_submit_secret', async () => {
    render(<SecretPromptDialog />);
    dispatchRequest({ refId: 'secret://abc', keyName: 'K', prompt: '' });
    await screen.findByRole('dialog');

    fireEvent.click(screen.getByText(/^Cancel$/));
    await waitFor(() => expect(screen.queryByRole('dialog')).toBeNull());
    expect(callCoreRpc).not.toHaveBeenCalled();
  });

  it('submit button disabled when value is empty', async () => {
    render(<SecretPromptDialog />);
    dispatchRequest({ refId: 'secret://abc', keyName: 'K', prompt: '' });
    await screen.findByRole('dialog');

    const submit = screen.getByText(/^Submit$/) as HTMLButtonElement;
    expect(submit.disabled).toBe(true);

    const input = screen.getByLabelText(/^Value$/i);
    fireEvent.change(input, { target: { value: 'x' } });
    expect(submit.disabled).toBe(false);
  });

  it('surfaces submit errors without dismissing', async () => {
    callCoreRpc.mockRejectedValueOnce(new Error('boom'));
    render(<SecretPromptDialog />);
    dispatchRequest({ refId: 'secret://abc', keyName: 'K', prompt: '' });
    await screen.findByRole('dialog');

    const input = screen.getByLabelText(/^Value$/i);
    fireEvent.change(input, { target: { value: 'v' } });
    fireEvent.click(screen.getByText(/^Submit$/));

    await waitFor(() => expect(screen.getByText(/boom/)).toBeTruthy());
    // Dialog still open
    expect(screen.queryByRole('dialog')).not.toBeNull();
  });
});

import { expect, test } from '@playwright/test';

import { bootRuntimeReadyGuestPage } from '../helpers/core-rpc';

test.describe('MCP Setup — Secret Collection Flow', () => {
  test('SecretPromptDialog appears on event, collects input, and submits without leaking to agent context', async ({
    page,
  }) => {
    await bootRuntimeReadyGuestPage(page);

    // Intercept all RPC calls to track what gets sent.
    // Mock mcp_setup_submit_secret since there's no real SecretRef in core memory.
    const rpcCalls: Array<{ method: string; params: Record<string, unknown> }> = [];
    await page.route('**/rpc', async (route, request) => {
      const body = JSON.parse(request.postData() || '{}');
      rpcCalls.push({ method: body.method, params: body.params });
      if (body.method === 'openhuman.mcp_setup_submit_secret') {
        await route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify({
            jsonrpc: '2.0',
            id: body.id,
            result: { ref: body.params.ref_id, fulfilled: true },
          }),
        });
      } else {
        await route.continue();
      }
    });

    // Simulate the core publishing a McpSetupSecretRequested event.
    // In production this comes via the socket → window event bridge.
    await page.evaluate(() => {
      window.dispatchEvent(
        new CustomEvent('openhuman:mcp-setup-secret-requested', {
          detail: {
            refId: 'secret://aabbccdd1122',
            keyName: 'NOTION_API_KEY',
            prompt: 'Enter your Notion integration token to connect.',
          },
        })
      );
    });

    // The dialog should appear
    const dialog = page.locator('[role="dialog"]');
    await expect(dialog).toBeVisible({ timeout: 5_000 });

    // Should show the key name and prompt
    await expect(dialog.locator('code')).toContainText('NOTION_API_KEY');
    await expect(dialog).toContainText('Enter your Notion integration token to connect.');

    // The input should be type=password (not leaking visually)
    const input = dialog.locator('input[type="password"]');
    await expect(input).toBeVisible();

    // Type a secret value
    await input.fill('ntn_secret_test_value_12345');

    // Submit
    const submitButton = dialog.locator('button[type="submit"]');
    await expect(submitButton).toBeEnabled();
    await submitButton.click();

    // Dialog should dismiss
    await expect(dialog).not.toBeVisible({ timeout: 5_000 });

    // Verify the RPC call was made with the correct ref but the value
    // only goes to submit_secret (never to any agent-facing method)
    const submitCall = rpcCalls.find(c => c.method === 'openhuman.mcp_setup_submit_secret');
    expect(submitCall).toBeTruthy();
    expect(submitCall!.params.ref_id).toBe('secret://aabbccdd1122');
    expect(submitCall!.params.value).toBe('ntn_secret_test_value_12345');

    // Critically: no agent-facing RPC (mcp_setup_test_connection,
    // mcp_setup_install_and_connect, or any chat/thread method) should
    // contain the raw secret value in its params.
    const agentFacingCalls = rpcCalls.filter(
      c =>
        c.method !== 'openhuman.mcp_setup_submit_secret' &&
        c.method !== 'openhuman.auth_store_session' &&
        c.method !== 'openhuman.auth_clear_session' &&
        c.method !== 'openhuman.config_set_onboarding_completed'
    );
    for (const call of agentFacingCalls) {
      const serialized = JSON.stringify(call.params);
      expect(serialized).not.toContain('ntn_secret_test_value_12345');
    }
  });

  test('cancel does not submit the secret', async ({ page }) => {
    await bootRuntimeReadyGuestPage(page);

    const rpcCalls: Array<{ method: string }> = [];
    await page.route('**/rpc', async (route, request) => {
      const body = JSON.parse(request.postData() || '{}');
      rpcCalls.push({ method: body.method });
      await route.continue();
    });

    await page.evaluate(() => {
      window.dispatchEvent(
        new CustomEvent('openhuman:mcp-setup-secret-requested', {
          detail: { refId: 'secret://cancel123456', keyName: 'API_KEY', prompt: 'Enter key' },
        })
      );
    });

    const dialog = page.locator('[role="dialog"]');
    await expect(dialog).toBeVisible({ timeout: 5_000 });

    // Click cancel
    const cancelButton = dialog.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Dialog should dismiss
    await expect(dialog).not.toBeVisible({ timeout: 3_000 });

    // No submit_secret call should have been made
    const submitCalls = rpcCalls.filter(c => c.method === 'openhuman.mcp_setup_submit_secret');
    expect(submitCalls).toHaveLength(0);
  });

  test.skip('secret input uses password masking by default', async ({ page }) => {
    await bootRuntimeReadyGuestPage(page);

    await page.evaluate(() => {
      window.dispatchEvent(
        new CustomEvent('openhuman:mcp-setup-secret-requested', {
          detail: { refId: 'secret://mask123456', keyName: 'TOKEN', prompt: '' },
        })
      );
    });

    const dialog = page.locator('[role="dialog"]');
    await expect(dialog).toBeVisible({ timeout: 5_000 });

    // Input is password-type (masked)
    const input = dialog.locator('#mcp-setup-secret-input');
    await expect(input).toHaveAttribute('type', 'password');

    // Toggle to show
    const showButton = dialog.getByRole('button', { name: /show/i });
    await showButton.click();
    await expect(input).toHaveAttribute('type', 'text');

    // Toggle back to hide
    const hideButton = dialog.getByRole('button', { name: /hide/i });
    await hideButton.click();
    await expect(input).toHaveAttribute('type', 'password');
  });
});

// @ts-nocheck
/**
 * MCP Setup Secret Dialog — desktop E2E (Appium / WDIO).
 *
 * Verifies that when the core publishes a `McpSetupSecretRequested` event,
 * the SecretPromptDialog appears in the native desktop WebView, collects
 * the user's input via a masked password field, and submits it only
 * through the `mcp_setup_submit_secret` RPC — never exposing the raw
 * value to any agent-facing channel.
 *
 * This is the Appium counterpart to the Playwright spec at
 * `test/playwright/specs/mcp-setup-secret-flow.spec.ts`. Both cover the
 * same functional contract; this one exercises it in the actual Tauri
 * desktop shell via CEF/WebView.
 */
import { waitForApp } from '../helpers/app-helpers';
import { resetApp } from '../helpers/reset-app';
import { startMockServer, stopMockServer } from '../mock-server';

const USER_ID = 'e2e-mcp-secret-dialog';

describe('MCP Setup — Secret Dialog', () => {
  before(async function () {
    this.timeout(90_000);
    await startMockServer();
    await waitForApp();
    await resetApp(USER_ID);
  });

  after(async () => {
    await stopMockServer();
  });

  it('dialog renders on McpSetupSecretRequested event', async () => {
    // Dispatch the event that the socket service forwards from core
    await browser.execute(() => {
      window.dispatchEvent(
        new CustomEvent('openhuman:mcp-setup-secret-requested', {
          detail: {
            refId: 'secret://e2e_test_ref1',
            keyName: 'TEST_API_KEY',
            prompt: 'Enter your test API key to verify the dialog.',
          },
        })
      );
    });

    // Wait for the dialog to appear
    const dialog = await $('[role="dialog"]');
    await dialog.waitForDisplayed({ timeout: 5_000 });

    // Verify key name and prompt text are shown
    const keyNameEl = await dialog.$('code');
    const keyNameText = await keyNameEl.getText();
    expect(keyNameText).toContain('TEST_API_KEY');

    const dialogText = await dialog.getText();
    expect(dialogText).toContain('Enter your test API key to verify the dialog.');
  });

  it('input is masked (type=password) by default', async () => {
    const input = await $('#mcp-setup-secret-input');
    const type = await input.getAttribute('type');
    expect(type).toBe('password');
  });

  it('show/hide toggle changes input type', async () => {
    const input = await $('#mcp-setup-secret-input');
    const dialog = await $('[role="dialog"]');

    // Find and click the "Show" button
    const showBtn = await dialog.$('button*=Show');
    await showBtn.click();
    expect(await input.getAttribute('type')).toBe('text');

    // Toggle back
    const hideBtn = await dialog.$('button*=Hide');
    await hideBtn.click();
    expect(await input.getAttribute('type')).toBe('password');
  });

  it('submit button is disabled when input is empty', async () => {
    const submitBtn = await $('[role="dialog"] button[type="submit"]');
    expect(await submitBtn.isEnabled()).toBe(false);
  });

  it('cancel dismisses the dialog without submitting', async () => {
    // Click cancel
    const dialog = await $('[role="dialog"]');
    const cancelBtn = await dialog.$('button*=Cancel');
    await cancelBtn.click();

    // Dialog should not be displayed
    await dialog.waitForDisplayed({ timeout: 3_000, reverse: true });
  });

  it('submit sends secret only to mcp_setup_submit_secret RPC', async () => {
    // Re-trigger a new dialog
    await browser.execute(() => {
      window.dispatchEvent(
        new CustomEvent('openhuman:mcp-setup-secret-requested', {
          detail: {
            refId: 'secret://e2e_test_ref2',
            keyName: 'SECOND_KEY',
            prompt: 'Second key prompt.',
          },
        })
      );
    });

    const dialog = await $('[role="dialog"]');
    await dialog.waitForDisplayed({ timeout: 5_000 });

    // Intercept outgoing RPC calls by patching the fetch in the page
    await browser.execute(() => {
      (window as any).__e2eRpcLog = [];
      const origFetch = window.fetch;
      window.fetch = async function (...args: any[]) {
        const [url, opts] = args;
        if (typeof url === 'string' && url.includes('/rpc') && opts?.body) {
          try {
            const body = JSON.parse(opts.body);
            (window as any).__e2eRpcLog.push({ method: body.method, params: body.params });
          } catch (_e) {
            /* intentionally empty — best-effort logging */
          }
        }
        return origFetch.apply(this, args);
      };
    });

    // Type a value and submit
    const input = await $('#mcp-setup-secret-input');
    await input.setValue('e2e_super_secret_value');

    const submitBtn = await dialog.$('button[type="submit"]');
    await submitBtn.click();

    // Give it a moment to process
    await browser.pause(1_000);

    // Retrieve the RPC log
    const rpcLog = (await browser.execute(() => (window as any).__e2eRpcLog)) as Array<{
      method: string;
      params: Record<string, unknown>;
    }>;

    // The submit_secret call should carry the ref and value
    const submitCall = rpcLog.find(c => c.method === 'openhuman.mcp_setup_submit_secret');
    expect(submitCall).toBeDefined();
    expect(submitCall!.params.ref_id).toBe('secret://e2e_test_ref2');
    expect(submitCall!.params.value).toBe('e2e_super_secret_value');

    // No other RPC call should contain the raw secret
    const otherCalls = rpcLog.filter(c => c.method !== 'openhuman.mcp_setup_submit_secret');
    for (const call of otherCalls) {
      const serialized = JSON.stringify(call.params);
      expect(serialized).not.toContain('e2e_super_secret_value');
    }

    // Cleanup: restore original fetch
    await browser.execute(() => {
      delete (window as any).__e2eRpcLog;
    });
  });
});

// Listens for `openhuman:mcp-setup-secret-requested` window events dispatched
// by `socketService` and renders a native input dialog so the user can hand
// the core a secret value out-of-band.
//
// The dialog deliberately uses `<input type="password">` so the value isn't
// echoed in the UI by default and never lands in clipboard history via
// triple-click. On submit, the value is POSTed straight to
// `openhuman.mcp_setup_submit_secret` and immediately cleared from React
// state — no logging, no Redux, no persistence on this side. The MCP setup
// agent only sees the opaque `ref://<hex>` ref returned by
// `mcp_setup_request_secret`; the raw value never enters the LLM context.
import { useCallback, useEffect, useId, useState } from 'react';

import { useT } from '../../lib/i18n/I18nContext';
import { callCoreRpc } from '../../services/coreRpcClient';
import { Button, ModalShell, TextField } from '../ui';

type Request = { refId: string; keyName: string; prompt: string };

function SecretPromptDialog() {
  const { t } = useT();
  const titleId = useId();
  const inputId = useId();
  const [request, setRequest] = useState<Request | null>(null);
  const [value, setValue] = useState('');
  const [reveal, setReveal] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const onRequest = (event: Event) => {
      const detail = (event as CustomEvent).detail as Request | undefined;
      if (!detail?.refId || !detail.keyName) return;
      setRequest(detail);
      setValue('');
      setReveal(false);
      setError(null);
      setSubmitting(false);
    };
    window.addEventListener('openhuman:mcp-setup-secret-requested', onRequest);
    return () => {
      window.removeEventListener('openhuman:mcp-setup-secret-requested', onRequest);
    };
  }, []);

  const reset = useCallback(() => {
    setRequest(null);
    setValue('');
    setReveal(false);
    setError(null);
    setSubmitting(false);
  }, []);

  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      if (!request || submitting || value.length === 0) return;
      setSubmitting(true);
      setError(null);
      try {
        await callCoreRpc({
          method: 'openhuman.mcp_setup_submit_secret',
          params: { ref_id: request.refId, value },
        });
        // Wipe local state on success — the value has now moved into the
        // core's process-local SETUP_SECRETS map; React doesn't need a
        // copy. Closing the dialog also drops the React-tree reference.
        reset();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setError(msg);
        setSubmitting(false);
      }
    },
    [request, submitting, value, reset]
  );

  // Cancel: do NOT call mcp_setup_submit_secret. The agent-side
  // `request_secret` will hit its 5-minute timeout and return an error
  // the agent can surface to the user, which is the right outcome here.
  const handleCancel = useCallback(() => {
    if (submitting) return;
    reset();
  }, [submitting, reset]);

  if (!request) return null;

  return (
    <ModalShell
      onClose={handleCancel}
      title={t('mcp.setup.secretDialog.title')}
      titleId={titleId}
      closePolicy={{ escape: !submitting, backdrop: !submitting, button: !submitting }}
      contentClassName="px-0 py-0"
      footer={
        <div className="flex items-center justify-end gap-3">
          <Button variant="tertiary" onClick={handleCancel} disabled={submitting}>
            {t('mcp.setup.secretDialog.cancel')}
          </Button>
          <Button
            type="submit"
            form="mcp-setup-secret-form"
            disabled={submitting || value.length === 0}>
            {submitting
              ? t('mcp.setup.secretDialog.submitting')
              : t('mcp.setup.secretDialog.submit')}
          </Button>
        </div>
      }>
      <form id="mcp-setup-secret-form" onSubmit={handleSubmit}>
        <div className="px-6 pt-2 pb-4">
          <p className="text-sm text-content-secondary">
            {t('mcp.setup.secretDialog.bodyPrefix')}{' '}
            <code className="px-1.5 py-0.5 rounded bg-surface-subtle text-content font-mono text-xs">
              {request.keyName}
            </code>
            {t('mcp.setup.secretDialog.bodySuffix')}
          </p>
          {request.prompt && (
            <p className="text-sm text-content-secondary mt-3 whitespace-pre-wrap">
              {request.prompt}
            </p>
          )}
        </div>

        <div className="px-6 pb-2">
          <label
            htmlFor={inputId}
            className="block text-xs font-medium text-content-secondary mb-1">
            {t('mcp.setup.secretDialog.inputLabel')}
          </label>
          <div className="flex items-stretch gap-2">
            <TextField
              id={inputId}
              type={reveal ? 'text' : 'password'}
              autoComplete="off"
              autoCorrect="off"
              spellCheck={false}
              value={value}
              onChange={e => setValue(e.target.value)}
              placeholder={t('mcp.setup.secretDialog.inputPlaceholder')}
              mono
              className="flex-1"
              autoFocus
              disabled={submitting}
            />
            <Button
              type="button"
              variant="secondary"
              size="sm"
              onClick={() => setReveal(v => !v)}
              disabled={submitting}>
              {reveal ? t('mcp.setup.secretDialog.hide') : t('mcp.setup.secretDialog.show')}
            </Button>
          </div>
          <p className="text-[11px] text-content-muted mt-2">
            {t('mcp.setup.secretDialog.privacyNote')}
          </p>
          {error && (
            <p className="text-xs text-coral-500 mt-2">
              {t('mcp.setup.secretDialog.errorPrefix')} {error}
            </p>
          )}
        </div>
      </form>
    </ModalShell>
  );
}

export default SecretPromptDialog;

//! End-to-end test for the MCP setup-agent flow.
//!
//! Exercises the ref machinery + install_and_connect path without going
//! through a real upstream registry — the test inserts an
//! `InstalledServer` row directly to stand in for what
//! `install_and_connect` would have synthesised from
//! `registry::registry_get`. The transport itself is the same
//! `test-mcp-stub` binary used by `mcp_registry_e2e.rs`.

// Exercises the gated `mcp_registry::setup` + `mcp_client` surface, so the
// whole suite is compiled only when the `mcp` feature is on — otherwise the
// slim build's `cargo test --no-default-features --tests` fails to compile against the removed APIs
// (#4799).
#![cfg(feature = "mcp")]

use std::collections::HashMap;
use std::time::Duration;

use openhuman_core::openhuman::config::Config;
use tinymcp::{SecretRef, SecretVault};

/// A vault for one test.
///
/// Owned rather than process-wide: the machinery moved to `tinymcp`, where a
/// library installing a global would make two hosts share one map and make its
/// own tests order-dependent.
fn vault() -> SecretVault {
    SecretVault::new()
}

#[tokio::test]
async fn request_secret_blocks_until_submit_then_resolves() {
    // Shared because the two halves run in different tasks — which is the
    // shape the real flow has: the model waits while a user interface answers.
    let v = std::sync::Arc::new(vault());
    // Caller mints + awaits in one task, fulfiller submits in another.
    // The exact API the setup_ops::request_secret handler uses.
    let (r, rx) = v.request("API_KEY").await;

    let r_for_submit = r.clone();
    let v_for_submit = std::sync::Arc::clone(&v);
    let submit_task = tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(20)).await;
        let submitted = v_for_submit
            .submit(&r_for_submit, "shh-secret".to_string())
            .await;
        assert!(submitted, "submit returns true the first time");
    });

    // The await side: must not return before fulfill is called.
    v.await_fulfillment(&r, rx)
        .await
        .expect("await_fulfillment completes once submit lands");
    submit_task.await.unwrap();

    // Resolve maps {KEY: ref} -> {KEY: value} without exposing value to
    // anywhere it shouldn't be.
    let mut refs = HashMap::new();
    refs.insert("API_KEY".to_string(), r.clone());
    let resolved = v.resolve(&refs).await.expect("resolves");
    assert_eq!(
        resolved,
        vec![("API_KEY".to_string(), "shh-secret".to_string())]
    );

    // The setup-agent contract: once install_and_connect persists the
    // values, the refs are gone.
    let _ = v.consume(&refs).await.expect("consumes");
    assert!(
        v.resolve(&refs).await.is_err(),
        "post-consume resolve fails"
    );
}

#[tokio::test]
async fn test_connection_against_stub_returns_tools() {
    let v = vault();
    use openhuman_core::openhuman::mcp::config_servers::McpStdioClient;

    // Mirror what setup_ops::test_connection does end-to-end, minus the
    // registry::registry_get step (we don't want to hit a real upstream
    // from CI). The point of this test is the spawn + initialize +
    // list_tools + teardown lifecycle the setup agent relies on.
    let (r, _rx) = v.request("ECHO_TOKEN").await;
    assert!(v.submit(&r, "ignored-by-stub".to_string()).await);

    let mut refs = HashMap::new();
    refs.insert("ECHO_TOKEN".to_string(), r);
    let env = v.resolve(&refs).await.expect("resolves");
    assert_eq!(env.len(), 1);

    let stub_path = env!("CARGO_BIN_EXE_test-mcp-stub");
