  it('clamps focus at the first server on ArrowUp', () => {
    render(
      <InstalledServerList
        servers={[SERVER_1, SERVER_2]}
        statuses={[]}
        selectedId={null}
        onSelect={() => {}}
        onBrowseCatalog={() => {}}
      />
